import numpy as np


def rnn_step(x_t, h_prev, Wx, Wh, b):
    return np.tanh(x_t @ Wx + h_prev @ Wh + b)


def run_rnn(sequence, Wx, Wh, b):
    h = np.zeros(Wh.shape[0])
    states = []
    for x_t in sequence:
        h = rnn_step(x_t, h, Wx, Wh, b)
        states.append(h)
    return np.array(states)


def label_sequence(seq):
    return "increasing" if seq[-1] > seq[0] else "decreasing"


rng = np.random.default_rng(0)
Wx = rng.standard_normal((1, 3)) * 0.5     # input -> hidden
Wh = rng.standard_normal((3, 3)) * 0.5     # hidden -> hidden (the "memory" connection)
b = np.zeros(3)

up = np.array([[0.1], [0.3], [0.5], [0.7], [0.9]])
states = run_rnn(up, Wx, Wh, b)
if states is None:
    print("run_rnn() returned None")
else:
    print("hidden states shape:", np.shape(states))
    print("final state (increasing):", np.round(states[-1], 4))
    print("final state (decreasing):", np.round(run_rnn(up[::-1], Wx, Wh, b)[-1], 4))
print("labels:", label_sequence(up.ravel()), label_sequence(up.ravel()[::-1]))
